-- Career evidence submission, review and disputes. No recruitment/payment writes.
CREATE ROLE nexustalent_evidence_writer NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB;
GRANT USAGE ON SCHEMA nexustalent TO nexustalent_evidence_writer;
GRANT SELECT, INSERT, UPDATE ON nexustalent.records TO nexustalent_evidence_writer;
GRANT EXECUTE ON FUNCTION nexustalent.actor_role() TO nexustalent_evidence_writer;
CREATE POLICY resolve_career_evidence ON nexustalent.records FOR SELECT TO nexustalent_scope_resolver USING (collection='careerEvidence' AND document_path='careerEvidence/'||NULLIF(current_setting('nexustalent.evidence_id',true),''));
CREATE FUNCTION nexustalent.bound_career_evidence() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT payload FROM nexustalent.records WHERE document_path='careerEvidence/'||NULLIF(current_setting('nexustalent.evidence_id',true),'') AND payload->>'id'=current_setting('nexustalent.evidence_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND payload->>'studentId'=current_setting('nexustalent.actor_uid',true)))
$$;
REVOKE ALL ON FUNCTION nexustalent.bound_career_evidence() FROM PUBLIC;
GRANT CREATE ON SCHEMA nexustalent TO nexustalent_scope_resolver;
ALTER FUNCTION nexustalent.bound_career_evidence() OWNER TO nexustalent_scope_resolver;
REVOKE CREATE ON SCHEMA nexustalent FROM nexustalent_scope_resolver;
GRANT EXECUTE ON FUNCTION nexustalent.bound_career_evidence() TO nexustalent_evidence_writer;
CREATE POLICY evidence_read ON nexustalent.records FOR SELECT TO nexustalent_evidence_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.evidence_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','REVIEW_CAREER_EVIDENCE','DISPUTE_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE') AND document_path NOT LIKE '%/%/%' AND ((collection='users' AND document_path='users/'||current_setting('nexustalent.actor_uid',true)) OR (collection='careerEvidence' AND document_path='careerEvidence/'||current_setting('nexustalent.evidence_id',true) AND payload->>'id'=current_setting('nexustalent.evidence_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND payload->>'studentId'=current_setting('nexustalent.actor_uid',true)))) OR (collection='students' AND (( ((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND current_setting('nexustalent.evidence_action',true)='CAREER_EVIDENCE_SUBMITTED' AND document_path='students/'||current_setting('nexustalent.actor_uid',true)) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) AND current_setting('nexustalent.evidence_action',true)='REVIEW_CAREER_EVIDENCE' AND document_path='students/'||((SELECT nexustalent.bound_career_evidence())->>'studentId'))))
 OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) AND current_setting('nexustalent.evidence_action',true)='REVIEW_CAREER_EVIDENCE' AND ((collection='institutions' AND ((SELECT nexustalent.bound_career_evidence())->>'sourceType')='institution' AND document_path='institutions/'||((SELECT nexustalent.bound_career_evidence())->>'sourceId')) OR (collection='employers' AND ((SELECT nexustalent.bound_career_evidence())->>'sourceType')='employer' AND document_path='employers/'||((SELECT nexustalent.bound_career_evidence())->>'sourceId'))))
 OR ((((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR ((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE'))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.evidence_action',true),'UTF8')),'hex') AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'action'=current_setting('nexustalent.evidence_action',true))));
CREATE POLICY evidence_insert ON nexustalent.records FOR INSERT TO nexustalent_evidence_writer WITH CHECK (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.evidence_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','REVIEW_CAREER_EVIDENCE','DISPUTE_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE') AND document_path NOT LIKE '%/%/%' AND (
 (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND current_setting('nexustalent.evidence_action',true)='CAREER_EVIDENCE_SUBMITTED' AND (collection='careerEvidence' AND document_path='careerEvidence/'||current_setting('nexustalent.evidence_id',true) AND payload->>'id'=current_setting('nexustalent.evidence_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND payload->>'studentId'=current_setting('nexustalent.actor_uid',true)))) AND payload->>'status'='submitted'
 AND payload->>'sourceType'='student_submission' AND payload->>'claimType' IN ('identity','institution','education','skill','project','internship','assessment','employment_outcome')
 AND length(payload->>'claimKey') BETWEEN 1 AND 200 AND length(payload->>'claimValue') BETWEEN 1 AND 4000
 AND COALESCE(payload->>'lineageHash','') ~ '^[a-f0-9]{64}$' AND COALESCE(payload->>'submittedAt','')<>''
 AND payload-ARRAY['id','studentId','claimType','claimKey','claimValue','sourceType','sourceId','evidenceUri','submittedAt','status','expiresAt','lineageHash']='{}'::jsonb)
 OR ((((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR ((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE'))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.evidence_action',true),'UTF8')),'hex')
 AND payload->>'eventId'=split_part(document_path,'/',2) AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'actorRole'=(SELECT nexustalent.actor_role()) AND payload->>'action'=current_setting('nexustalent.evidence_action',true)
 AND payload->>'requestId'=current_setting('nexustalent.request_id',true) AND payload->'immutable'='true'::jsonb
 AND ((current_setting('nexustalent.evidence_action',true)='CAREER_EVIDENCE_SUBMITTED' AND payload->>'subjectStudentId'=current_setting('nexustalent.actor_uid',true) AND payload->>'evidenceId'=current_setting('nexustalent.evidence_id',true)) OR (current_setting('nexustalent.evidence_action',true)<>'CAREER_EVIDENCE_SUBMITTED' AND payload->'ids'=jsonb_build_array(current_setting('nexustalent.evidence_id',true)))))));
CREATE POLICY evidence_update ON nexustalent.records FOR UPDATE TO nexustalent_evidence_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.evidence_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','REVIEW_CAREER_EVIDENCE','DISPUTE_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE') AND document_path NOT LIKE '%/%/%' AND current_setting('nexustalent.evidence_action',true)<>'CAREER_EVIDENCE_SUBMITTED' AND (((collection='careerEvidence' AND document_path='careerEvidence/'||current_setting('nexustalent.evidence_id',true) AND payload->>'id'=current_setting('nexustalent.evidence_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) OR (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND payload->>'studentId'=current_setting('nexustalent.actor_uid',true))))) OR ((collection='students' AND (( ((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.evidence_action',true) IN ('CAREER_EVIDENCE_SUBMITTED','DISPUTE_CAREER_EVIDENCE')) AND current_setting('nexustalent.evidence_action',true)='CAREER_EVIDENCE_SUBMITTED' AND document_path='students/'||current_setting('nexustalent.actor_uid',true)) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) AND current_setting('nexustalent.evidence_action',true)='REVIEW_CAREER_EVIDENCE' AND document_path='students/'||((SELECT nexustalent.bound_career_evidence())->>'studentId')))) AND ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.evidence_action',true) IN ('REVIEW_CAREER_EVIDENCE','RESOLVE_CAREER_EVIDENCE_DISPUTE')) AND current_setting('nexustalent.evidence_action',true)='REVIEW_CAREER_EVIDENCE')));
CREATE FUNCTION nexustalent.guard_evidence_write() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a text:=current_setting('nexustalent.evidence_action',true); prev text; nxt text; e jsonb; expected jsonb; fields text[];
BEGIN
 IF NOT pg_has_role(current_user,'nexustalent_evidence_writer','MEMBER') OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF split_part(NEW.document_path,'/',1)='careerEvidence' AND NOT EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='students/'||current_setting('nexustalent.actor_uid',true) AND payload->>'id'=current_setting('nexustalent.actor_uid',true)) THEN RAISE EXCEPTION 'Student identity required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.collection='students' AND a='REVIEW_CAREER_EVIDENCE' THEN
  e:=nexustalent.bound_career_evidence();
  IF e->>'status' IS DISTINCT FROM 'verified' OR e->>'reviewedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true) OR e->>'studentId' IS DISTINCT FROM OLD.payload->>'id' THEN RAISE EXCEPTION 'Verified evidence binding required' USING ERRCODE='23514'; END IF;
  expected:=CASE WHEN jsonb_typeof(OLD.payload->'evidenceIds')='array' THEN OLD.payload->'evidenceIds' ELSE '[]'::jsonb END;
  IF NOT expected ? current_setting('nexustalent.evidence_id',true) THEN expected:=expected||jsonb_build_array(current_setting('nexustalent.evidence_id',true)); END IF;
  IF NEW.payload IS DISTINCT FROM (OLD.payload||jsonb_build_object('evidenceIds',expected)) THEN RAISE EXCEPTION 'Unrelated student modification' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.collection<>'careerEvidence' THEN RAISE EXCEPTION 'Unrelated evidence modification' USING ERRCODE='23514'; END IF;
 prev:=OLD.payload->>'status'; nxt:=NEW.payload->>'status';
 IF COALESCE(NEW.payload->>'lineageHash','') !~ '^[a-f0-9]{64}$' OR NEW.payload->>'lineageHash' IS NOT DISTINCT FROM OLD.payload->>'lineageHash' THEN RAISE EXCEPTION 'New lineage required' USING ERRCODE='23514'; END IF;
 IF a='REVIEW_CAREER_EVIDENCE' THEN
  fields:=ARRAY['status','reviewedAt','reviewedBy','rejectionReason','disputeStatus','lineageHash'];
  IF NOT COALESCE((prev,nxt) IN (('submitted','under_review'),('submitted','rejected'),('under_review','verified'),('under_review','rejected'),('verified','under_review'),('verified','expired'),('expired','under_review')),false)
   OR NEW.payload->>'reviewedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true) OR COALESCE(NEW.payload->>'reviewedAt','')='' OR (nxt='rejected' AND length(trim(COALESCE(NEW.payload->>'rejectionReason','')))=0)
   OR (nxt='verified' AND (NEW.payload->>'disputeStatus' IS DISTINCT FROM 'none' OR NOT COALESCE(
    (OLD.payload->>'sourceType'='institution' AND EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='institutions/'||(OLD.payload->>'sourceId') AND payload->>'empanelmentStatus'='empanelled'))
    OR (OLD.payload->>'sourceType'='employer' AND EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='employers/'||(OLD.payload->>'sourceId') AND payload->>'verificationStatus'='verified')),false)))
   OR (nxt='verified' AND NULLIF(OLD.payload->>'expiresAt','') IS NOT NULL AND (OLD.payload->>'expiresAt')::timestamptz<=clock_timestamp())
   OR (nxt='expired' AND (NULLIF(OLD.payload->>'expiresAt','') IS NULL OR (OLD.payload->>'expiresAt')::timestamptz>clock_timestamp()))
  THEN RAISE EXCEPTION 'Invalid evidence review' USING ERRCODE='23514'; END IF;
 ELSIF a='DISPUTE_CAREER_EVIDENCE' THEN
  fields:=ARRAY['disputeStatus','disputeReason','disputeOpenedAt','disputeOpenedBy','lineageHash'];
  IF COALESCE(prev,'') NOT IN ('verified','rejected','expired','under_review') OR NEW.payload->>'disputeStatus' IS DISTINCT FROM 'open' OR NEW.payload->>'disputeOpenedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true) OR length(trim(COALESCE(NEW.payload->>'disputeReason',''))) NOT BETWEEN 10 AND 4000 THEN RAISE EXCEPTION 'Invalid evidence dispute' USING ERRCODE='23514'; END IF;
 ELSIF a='RESOLVE_CAREER_EVIDENCE_DISPUTE' THEN
  fields:=ARRAY['status','disputeStatus','disputeReason','disputeResolvedAt','disputeResolvedBy','reviewedAt','reviewedBy','rejectionReason','lineageHash'];
  IF OLD.payload->>'disputeStatus' IS DISTINCT FROM 'open' OR NEW.payload->>'disputeStatus' IS DISTINCT FROM 'resolved' OR NEW.payload->>'disputeResolvedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true) OR NEW.payload->>'reviewedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true)
  OR length(trim(COALESCE(NEW.payload->>'disputeReason',''))) NOT BETWEEN 10 AND 4000 OR NOT COALESCE(nxt IN (prev,'under_review','rejected'),false) THEN RAISE EXCEPTION 'Invalid evidence dispute resolution' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Invalid evidence action' USING ERRCODE='23514'; END IF;
 IF (NEW.payload-fields) IS DISTINCT FROM (OLD.payload-fields) THEN RAISE EXCEPTION 'Evidence provenance is immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END
$$;
CREATE TRIGGER evidence_write_guard BEFORE INSERT OR UPDATE ON nexustalent.records FOR EACH ROW EXECUTE FUNCTION nexustalent.guard_evidence_write();
REVOKE ALL ON FUNCTION nexustalent.guard_evidence_write() FROM PUBLIC;
